import java.util.*;
import java.util.regex.*;
import java.util.stream.*;

public class Main {
    private static final Pattern UNDERSCORE = Pattern.compile("_");

    private static int maxOutsideWord(String text) {
        return UNDERSCORE.splitAsStream(text)
                .mapToInt(String::length)
                .max()
                .orElse(0);
    }

    private static int countInsideWords(String text) {
        return UNDERSCORE.splitAsStream(text)
                .mapToInt(word -> word.isEmpty() ? 0 : 1)
                .sum();
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        String s = sc.next();
        boolean openParenthesis = false;
        StringBuilder sb = new StringBuilder();
        int maxOutSide = 0;
        int nbrInside = 0;
        for (int i = 0; i < n; i++) {
            char c = s.charAt(i);
            if (c == '(') {
                if (!openParenthesis) {
                    maxOutSide = Math.max(maxOutSide, maxOutsideWord(sb.toString()));
                }
                openParenthesis = true;
                sb.setLength(0);
            } else if (c == ')') {
                openParenthesis = false;
                nbrInside += countInsideWords(sb.toString());
                sb.setLength(0);
            } else {
                sb.append(c);
            }
        }
        maxOutSide = Math.max(maxOutSide, maxOutsideWord(sb.toString()));
        System.out.println(maxOutSide + " " + nbrInside);
    }
}
